// hscli config HARNESS: the harness's files, generated in hscli's state
// directory from what the API says the key may do, and printed. The user's
// own harness configuration is never touched, and no
// generated file holds the key: each reads it from the key file.
//
// hscli shell-init: shell functions that start each harness with them,
// since hscli itself never starts a program.
import { fs } from "hull:fs";
import * as api from "../lib/api.js";
import * as paths from "../lib/paths.js";

export const FILES = {
    pi: ["pi-herding-sparks.js"],
    opencode: ["opencode.json"],
    aider: ["aider-models.json", "aider-settings.yml"],
};

// Each model the key may use, with what a harness must be told.
function models(d) {
    return d.models.map((m) => {
        const context = d.key.limits.max_prompt_tokens ?? m.max_model_len;
        if (!context) throw new api.HscliError(`the API gives no context for ${m.id}`);
        return { id: m.id, context, output: d.key.limits.max_tokens ?? 16384 };
    });
}

function header(d, harness) {
    return `Generated by hscli config ${harness} for key ${d.key.key_id} (policy ${d.key.policy}). `
        + "Regenerated each time the harness is started through hscli; edits are lost.";
}

export function generate(harness, d, base, keyFile) {
    const ms = models(d);
    if (harness === "pi") {
        // Pi's own provider settings for vLLM's OpenAI API: no developer role,
        // no reasoning_effort, thinking through the chat template.
        const compat = { supportsDeveloperRole: false, supportsReasoningEffort: false, supportsStore: false,
                         supportsUsageInStreaming: true, maxTokensField: "max_tokens", thinkingFormat: "qwen-chat-template" };
        const list = ms.map((m) => ({ id: m.id, name: `${m.id} (Herding Sparks)`, reasoning: true, input: ["text"],
            cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, contextWindow: m.context, maxTokens: m.output, compat }));
        return { "pi-herding-sparks.js": `// ${header(d, "pi")}
import { readFileSync } from "node:fs";

export default function (pi) {
  pi.registerProvider("herding-sparks", {
    name: "Herding Sparks",
    baseUrl: ${JSON.stringify(base)},
    api: "openai-completions",
    apiKey: readFileSync(${JSON.stringify(keyFile)}, "utf8").trim(),
    models: ${JSON.stringify(list, null, 2).replace(/\n/g, "\n    ")},
  });
}
` };
    }
    if (harness === "opencode") {
        const doc = { $schema: "https://opencode.ai/config.json", _comment: header(d, "opencode"),
            provider: { "herding-sparks": { npm: "@ai-sdk/openai-compatible", name: "Herding Sparks",
                options: { baseURL: base, apiKey: `{file:${keyFile}}` },
                models: Object.fromEntries(ms.map((m) => [m.id, { name: `${m.id} (Herding Sparks)`,
                    limit: { context: m.context, output: m.output } }])) } } };
        delete doc._comment;   // OpenCode's schema has no comment field
        doc.model = `herding-sparks/${ms[0].id}`;   // hs-opencode starts on it; the user's own config is merged under
        return { "opencode.json": JSON.stringify(doc, null, 2) + "\n" };
    }
    if (harness === "aider") {
        const meta = Object.fromEntries(ms.map((m) => [`openai/${m.id}`, { max_input_tokens: m.context,
            max_output_tokens: m.output, max_tokens: m.output, litellm_provider: "openai", mode: "chat",
            input_cost_per_token: 0, output_cost_per_token: 0 }]));
        // The API requires max_tokens, which aider doesn't send unless told.
        const settings = ms.map((m) => `- name: openai/${m.id}\n  extra_params:\n    max_tokens: ${m.output}\n`).join("");
        return { "aider-models.json": JSON.stringify(meta, null, 2) + "\n", "aider-settings.yml": `# ${header(d, "aider")}\n${settings}` };
    }
    throw new api.HscliError(`no harness '${harness}': give pi, opencode or aider`, 2);
}

export async function config(ctx, args) {
    const [harness, ...rest] = args;
    const quiet = rest.includes("--quiet");
    if (!harness || !FILES[harness] || rest.some((a) => a !== "--quiet")) {
        ctx.stderr.write("usage: hscli config pi|opencode|aider [--quiet]\n");
        return 2;
    }
    api.host(ctx.env);
    const key = api.readKey();
    const d = await api.describe(ctx.env, key);
    const w = api.expiryWarning(d.key.expires);
    if (w) ctx.stderr.write(w + "\n");     // also with --quiet: hs-pi and the others show it at start
    const files = generate(harness, d, api.baseUrl(ctx.env), paths.real("api-key"));
    for (const [name, text] of Object.entries(files)) {
        fs.write(`@state/${name}`, text);
        if (!quiet) ctx.stdout.write(`# ${paths.real(name)}\n${text}`);
    }
    return 0;
}

export function shellInit(ctx, args) {
    if (args.length) { ctx.stderr.write("usage: eval \"$(hscli shell-init)\"\n"); return 2; }
    const p = (f) => paths.shq(paths.real(f));
    const model = "qwen3_8-flash-next-fp4-local";
    ctx.stdout.write(`# hscli shell-init: start a harness with the Herding Sparks API.
# Each function regenerates the harness's files from the key's own limits.
hs-pi() { hscli config pi --quiet && pi -e ${p("pi-herding-sparks.js")} --model herding-sparks/${model} "$@"; }
hs-opencode() { hscli config opencode --quiet && OPENCODE_CONFIG=${p("opencode.json")} opencode "$@"; }
hs-aider() { hscli config aider --quiet && OPENAI_API_BASE="https://$HSCLI_API_HOST/v1" OPENAI_API_KEY="$(cat ${p("api-key")})" \\
    aider --model openai/${model} --model-metadata-file ${p("aider-models.json")} --model-settings-file ${p("aider-settings.yml")} "$@"; }
`);
    return 0;
}
